$('talentBtn').onclick=()=>{finishForgePresentation();talentRefundMode=false;talentRefundDraft={};showTalents();};$('homeBtn').onclick=()=>go('world');
$('helpBtn').onclick=()=>{finishForgePresentation();modal(`<div class="eyebrow">WELCOME, FORGEBEARER</div><h2>炉火未熄，旅途开始。</h2><p>点击世界地图上的矮人领地，再选择据点展开自动远征。</p><ol><li>三个构筑技能预设可自由试用，装备与套装需通过战斗或融合获得。</li><li>远征获得装备、经验和材料；挑战首领推进商队线索。</li><li>点击装备图标查看与穿戴，点击技能槽更换战技。</li><li>把材料放入五个锻造槽，打造新装备。</li></ol><p>一份存档固定一名矮人主角。其他种族领地当前仅为地图预览。没有硬性流派免疫。</p><p>自动远征开启且已击败该区域普通敌人后，离线驻扎收益最多4小时。当前浏览器存档，可在设置中导出备份。</p><button class="primary" id="beginBtn">前往黑炉山脉</button>`);};
function downloadSave(raw,filename){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([raw],{type:'application/json'}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
$('settingsBtn').onclick=()=>{finishForgePresentation();const backups=listBackups(localStorage);modal(`<h2>旅途存档</h2><p>v0.4 装备系统使用独立的新存档。旧版原始数据未删除；此版不能导入旧装备格式。保存仅限当前浏览器，没有云同步。</p><div class="row"><button id="exportBtn">导出当前存档</button><button id="importBtn">导入 v0.4 存档</button><button id="restartBtn" class="danger">重新开始</button></div><input id="importFile" type="file" accept="application/json" hidden>${backups.length?'<h3>可恢复的原始备份</h3>'+backups.map(b=>`<div class="backupRow"><span>${b.label}</span><button data-backup="${esc(b.key)}">导出备份</button></div>`).join(''):'<p>暂无旧版备份。</p>'}`);$('exportBtn').onclick=()=>{save();downloadSave(JSON.stringify(s),'灰冠诸境-v0.4-布洛克.json');};$('importBtn').onclick=()=>$('importFile').click();$('importFile').onchange=async ev=>{try{let v=JSON.parse(await ev.target.files[0].text());if(!validSave(v))throw Error();if(!confirm('导入将替换当前进度，替换前会保留原始备份。确定继续？'))return;backupRaw(localStorage,JSON.stringify(s),'before-import');normalizeSkillSlots(v);normalizeTalents(v);normalizeMaterials(v);s=v;s.running=false;e=null;lastForgeResult=null;selected=s.equip.weapon;save();render();$('modal').close();toast('存档已导入，之前进度已备份');}catch{toast('需要有效的 v0.4 存档，当前进度未改变');}};$('restartBtn').onclick=()=>{if(confirm('确定重新开始？当前进度会保留为可导出的原始备份。')){backupRaw(localStorage,JSON.stringify(s),'before-restart');s=fresh();e=null;logs=[];selection=[];lastForgeResult=null;selected=s.equip.weapon;view='world';save();render();$('modal').close();toast('新的旅程已经开始，旧进度已备份');}};};
function tick(now){if(document.hidden)return;if(s.running&&now-lastStep>1100){lastStep=now;if(!e||e.done){if(now>=nextAt)start(false);}else{logs.unshift(...step(s,e).reverse());logs=logs.slice(0,30);hitUntil=now+280;if(e.done){if(e.win){let it=reward(s,e);logs.unshift(e.boss?'首领已击败，获得新的商队线索。':'战斗胜利 · 获得'+LOCS[s.location].mat);if(e.rewardNotes)logs.unshift(...e.rewardNotes);if(it)logs.unshift('获得 '+RARITY[it.rarity]+' '+it.name);if(e.boss){s.running=false;toast('首领战胜利！新线索已记录。');}}else{s.running=false;logs.unshift('已撤回营地，提升装备或等级后重试。');toast('战斗失败，没有首领奖励冷却');}if(s.stopAfterBattle){s.running=false;s.stopAfterBattle=false;toast('本场已结束，远征已停止');}nextAt=now+1800;hud();if(['inventory','journal','loadouts'].includes(view))render();save();}if($('combatMessage'))$('combatMessage').textContent=logs[0];battleHud();}}}
function portrait(canvas){if(!canvas)return;let pc=canvas.getContext('2d');pc.clearRect(0,0,160,150);pc.imageSmoothingEnabled=false;let rect=(x,y,w,h,c)=>{pc.fillStyle=c;pc.fillRect(x,y,w,h)};rect(38,128,88,7,'#10271b');rect(53,80,53,40,'#536f4f');rect(48,86,15,24,'#85956b');rect(100,86,16,24,'#85956b');rect(62,42,37,32,'#cbb27c');rect(55,37,50,12,'#718263');rect(61,28,37,12,'#9ea279');rect(77,23,9,27,'#d0b574');rect(60,59,43,12,'#ddc597');rect(64,68,35,31,'#bfab81');rect(70,94,24,9,'#bfab81');rect(67,53,7,5,'#203a2c');rect(88,53,7,5,'#203a2c');rect(75,62,13,7,'#a07a4b');rect(58,109,17,17,'#3f5940');rect(89,109,17,17,'#3f5940');rect(120,60,6,66,'#917146');rect(108,53,28,18,'#839477');rect(110,53,24,4,'#b4bf91');rect(47,101,13,8,'#cbb27c');}
let frame=0;function animate(t){if(t-frame>70){frame=t;if(view==='battle')drawScene($('scene'),{location:s.location,fighting:s.running&&!!e&&!e.done,boss:!!e?.boss,heroHp:e?e.heroHp/stats(s).hp:1,enemyHp:e?e.hp/e.max:1,time:t,hit:Date.now()<hitUntil});if(view==='forge'&&forgeTab==='fusion'&&$('forgeCanvas'))drawForge($('forgeCanvas'),t);if(view==='merchant')drawMerchant($('merchantCanvas'),t);}requestAnimationFrame(animate);}render();portrait($('portrait'));requestAnimationFrame(animate);setInterval(()=>{tick(Date.now());battleHud();merchantTick();},250);setInterval(()=>{if(!document.hidden)save();},10000);window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();else{if(s.stopAfterBattle)return;let r=offline(s);if(r){e=null;toast(`离线驻扎：+${r.gold}金币，+${r.xp}经验${premiumLootText(r.materialLoot)?' · '+premiumLootText(r.materialLoot):''}`);render();save();}}});if(supportGrant.granted)modal('<h2>开发测试补给已到账</h2><p>金币 +5,000 · 未分配天赋点 +30 · 回忆之果 +3</p><p>这是本存档的一次性测试补给，刷新不会重复发放。现有进度与已分配天赋保持不变。</p>');else if(supportGrant.failed)toast('本地存储不可用，测试补给暂未发放，请恢复存储后刷新');else if(loaded.notice)modal(`<h2>装备系统已升级</h2><div class="versionNotice">${esc(loaded.notice)}</div><p>八个装备栏位、固定数值词条与2/4件套装已启用。新存档从普通初始装备开始，不赠送成套至臻装备。</p><button class="primary" data-dismissupgrade="1">开启新旅程</button>`);else if(away)toast(`离线${away.minutes}分钟：+${away.gold}金币，+${away.xp}经验，+${away.mat}材料${premiumLootText(away.materialLoot)?' · '+premiumLootText(away.materialLoot):''}`);save();
